#[test]
fn unit_expressions_agree() {
    super::check_unit_exprs::<Volume>(Volume::new);
}

#[test]
fn unit_metadata() {
    let info = Volume::<f64>::INFO;
    assert_eq!(info.name, "Volume");
    assert_eq!(info.units.len(), VolumeUnit::ALL.len());
    for (&unit, unit_info) in VolumeUnit::ALL.iter().zip(info.units) {
        assert_eq!(unit.info(), unit_info);
        assert_eq!(format!("{unit:?}"), unit_info.singular);
        assert_eq!(unit.abbreviation(), unit_info.abbreviation);
        assert_eq!(unit.all_abbreviations(), unit_info.abbreviations);
    }
    assert_eq!(info.base_unit, VolumeUnit::CubicMeter.info());
}

#[test]
